const RIGHT_DOCK_STORAGE_KEY = "pixieed:draw2:right-dock:v1";
const AUDIO_DOCK_STORAGE_KEY = "pixieed:draw2:audio-dock:v2";
const RAIL_LAYOUT_STORAGE_KEY = "pixieed:draw2:rail-layout:v1";
const DRAW2_THEME_STORAGE_KEY = "pixieed:draw2:theme:v1";
const DRAW2_DETAIL_MODE_STORAGE_KEY = "pixieed:draw2:detail-mode:v1";
// The palette is a compact, persistent strip above the active panel. Keep
// its default small enough that the Color surface remains usable, while
// retaining a bounded ratio for the user-controlled splitter.
const RIGHT_DOCK_DEFAULT_PALETTE_RATIO = 0.18;
// Widened so the splitter can travel almost to either extreme (Aseprite-style
// fully variable panels), while RIGHT_DOCK_MIN_PALETTE_PX/RIGHT_DOCK_MIN_CUSTOM_PX
// below still keep each side from shrinking below a usable floor.
const RIGHT_DOCK_MIN_PALETTE_RATIO = 0.04;
const RIGHT_DOCK_MAX_PALETTE_RATIO = 0.88;
const RIGHT_DOCK_RESIZE_HANDLE_PX = 12;

type AudioDockPanelId =
  | "browser"
  | "tracks"
  | "mixer"
  | "inspector"
  | "automation"
  | "fx";

interface AudioDockPanelDefinition {
  readonly id: AudioDockPanelId;
  readonly label: string;
  readonly detail: string;
}

const AUDIO_DOCK_PANEL_REGISTRY: readonly AudioDockPanelDefinition[] = [
  { id: "browser", label: "Browser", detail: "Samples / MIDI / FX" },
  { id: "tracks", label: "Tracks", detail: "Audio lanes" },
  { id: "mixer", label: "Mixer", detail: "Gain / Pan / Mute" },
  { id: "inspector", label: "Inspector", detail: "Selected track" },
  { id: "automation", label: "Automation", detail: "Tick-linked control" },
  { id: "fx", label: "FX Chain", detail: "Insert effects" },
];

const AUDIO_DOCK_DEFAULT_PANELS: readonly AudioDockPanelId[] = [
  "tracks",
];

function isAudioDockPanelId(value: string): value is AudioDockPanelId {
  return AUDIO_DOCK_PANEL_REGISTRY.some((definition) =>
    definition.id === value
  );
}

function normalizeAudioDockPanels(
  panels: readonly AudioDockPanelId[],
): AudioDockPanelId[] {
  const selected = new Set(panels);
  const ordered = AUDIO_DOCK_PANEL_REGISTRY
    .map((definition) => definition.id)
    .filter((panelId) => selected.has(panelId));
  return ordered.length > 0 ? ordered : [...AUDIO_DOCK_DEFAULT_PANELS];
}

function readAudioDockLayout(storage: Storage | undefined): AudioDockPanelId[] {
  if (storage === undefined) return [...AUDIO_DOCK_DEFAULT_PANELS];
  try {
    const raw = storage.getItem(AUDIO_DOCK_STORAGE_KEY);
    if (raw === null) return [...AUDIO_DOCK_DEFAULT_PANELS];
    const parsed = JSON.parse(raw) as { panels?: unknown };
    const panels = Array.isArray(parsed.panels)
      ? [
        ...new Set(
          parsed.panels.filter(
            (value): value is string =>
              typeof value === "string" && isAudioDockPanelId(value),
          ),
        ),
      ].slice(0, AUDIO_DOCK_PANEL_REGISTRY.length) as AudioDockPanelId[]
      : [];
    return normalizeAudioDockPanels(panels);
  } catch {
    return [...AUDIO_DOCK_DEFAULT_PANELS];
  }
}

function writeAudioDockLayout(
  storage: Storage | undefined,
  panels: readonly AudioDockPanelId[],
): void {
  if (storage === undefined) return;
  try {
    storage.setItem(AUDIO_DOCK_STORAGE_KEY, JSON.stringify({ panels }));
  } catch {
    // Layout preferences are best effort and never block Audio editing.
  }
}

// Shared desktop rail bounds. The palette keeps one compact swatch row at its
// minimum; the custom dock keeps its tab strip plus a small scroll viewport so
// the active editor never becomes an invisible sliver while the splitter is
// moved toward the palette maximum.
const RIGHT_DOCK_MIN_PALETTE_PX = 40;
const RIGHT_DOCK_MIN_CUSTOM_PX = 176;
// The PC rail keeps the color editor, form controls, and focus rings usable
// down to this width while being dragged open. Dragging past
// WORKSPACE_RAIL_SNAP_PX instead snaps the rail fully closed (see
// WORKSPACE_RAIL_SNAP_PX below) rather than forcing that authoring surface
// into an unusably tiny sliver -- this is how every rail in this workspace
// now reaches "minimum" Aseprite-style: snap-closed, not infinite squeeze.
const WORKSPACE_RIGHT_RAIL_MIN_PX = 280;
const WORKSPACE_RIGHT_RAIL_RESPONSIVE_MIN_PX = 200;
const WORKSPACE_RIGHT_RAIL_MAX_PX = 760;
const WORKSPACE_GAME_LEFT_RAIL_MIN_PX = 224;
const WORKSPACE_AUDIO_LEFT_RAIL_MIN_PX = 220;
const WORKSPACE_LEFT_RAIL_MAX_PX = 320;
const WORKSPACE_TIMELINE_MIN_PX = 132;
const WORKSPACE_TIMELINE_MAX_PX = 640;
// Dragging a rail's handle past this point (from its open side) snaps that
// rail fully closed instead of clamping to its MIN_PX; dragging back out
// past the same point reopens it at a usable width. Shared by the left,
// right, and timeline resize handles so every rail closes the same way.
const WORKSPACE_RAIL_SNAP_PX = 96;

interface RailLayoutPreference {
  readonly sharedLeftWidth: number;
  readonly audioLeftWidth: number;
  readonly rightWidth: number;
  readonly timelineHeight: number;
  readonly gameLeftCollapsed: boolean;
  readonly audioLeftCollapsed: boolean;
  readonly timelineCollapsed: boolean;
}

const clampRailLayoutValue = (
  value: number,
  minimum: number,
  maximum: number,
): number => Math.max(minimum, Math.min(maximum, Math.round(value)));

function defaultRailLayoutPreference(): RailLayoutPreference {
  return {
    sharedLeftWidth: 52,
    audioLeftWidth: 244,
    rightWidth: 320,
    timelineHeight: 260,
    gameLeftCollapsed: false,
    audioLeftCollapsed: false,
    timelineCollapsed: false,
  };
}

function readRailLayoutPreference(
  storage: Storage | undefined,
): RailLayoutPreference {
  const fallback = defaultRailLayoutPreference();
  if (storage === undefined) return fallback;
  try {
    const raw = storage.getItem(RAIL_LAYOUT_STORAGE_KEY);
    if (raw === null) return fallback;
    const parsed = JSON.parse(raw) as {
      sharedLeftWidth?: unknown;
      audioLeftWidth?: unknown;
      rightWidth?: unknown;
      timelineHeight?: unknown;
      gameLeftCollapsed?: unknown;
      audioLeftCollapsed?: unknown;
      timelineCollapsed?: unknown;
    };
    const numberOr = (value: unknown, defaultValue: number): number =>
      typeof value === "number" && Number.isFinite(value)
        ? value
        : defaultValue;
    return {
      sharedLeftWidth: clampRailLayoutValue(
        numberOr(parsed.sharedLeftWidth, fallback.sharedLeftWidth),
        40,
        520,
      ),
      audioLeftWidth: clampRailLayoutValue(
        numberOr(parsed.audioLeftWidth, fallback.audioLeftWidth),
        WORKSPACE_AUDIO_LEFT_RAIL_MIN_PX,
        WORKSPACE_LEFT_RAIL_MAX_PX,
      ),
      rightWidth: clampRailLayoutValue(
        numberOr(parsed.rightWidth, fallback.rightWidth),
        WORKSPACE_RIGHT_RAIL_RESPONSIVE_MIN_PX,
        WORKSPACE_RIGHT_RAIL_MAX_PX,
      ),
      timelineHeight: clampRailLayoutValue(
        numberOr(parsed.timelineHeight, fallback.timelineHeight),
        WORKSPACE_TIMELINE_MIN_PX,
        WORKSPACE_TIMELINE_MAX_PX,
      ),
      gameLeftCollapsed: typeof parsed.gameLeftCollapsed === "boolean"
        ? parsed.gameLeftCollapsed
        : fallback.gameLeftCollapsed,
      audioLeftCollapsed: typeof parsed.audioLeftCollapsed === "boolean"
        ? parsed.audioLeftCollapsed
        : fallback.audioLeftCollapsed,
      timelineCollapsed: typeof parsed.timelineCollapsed === "boolean"
        ? parsed.timelineCollapsed
        : fallback.timelineCollapsed,
    };
  } catch {
    return fallback;
  }
}

function writeRailLayoutPreference(
  storage: Storage | undefined,
  preference: RailLayoutPreference,
): void {
  if (storage === undefined) return;
  try {
    storage.setItem(RAIL_LAYOUT_STORAGE_KEY, JSON.stringify(preference));
  } catch {
    // Layout preferences are best effort and never block editing.
  }
}

function readWorkspaceDetailMode(storage: Storage | undefined): WorkspaceDetailMode {
  if (storage === undefined) return "guided";
  try {
    return resolveWorkspaceDetailMode(
      storage.getItem(DRAW2_DETAIL_MODE_STORAGE_KEY),
    );
  } catch {
    return "guided";
  }
}

function writeWorkspaceDetailMode(
  storage: Storage | undefined,
  mode: WorkspaceDetailMode,
): void {
  if (storage === undefined) return;
  try {
    storage.setItem(DRAW2_DETAIL_MODE_STORAGE_KEY, mode);
  } catch {
    // Detail preference is best effort and never blocks editing.
  }
}

