  const createPlatformStarterMap = (
    mapId: string,
    width: number,
    height: number,
    platforms: readonly (readonly [number, number, number])[],
  ): GameTilemapDocument => {
    const cells: Array<GameTilemapDocument["cells"][number]> = [];
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        if (y === height - 1 || x === 0 || x === width - 1) {
          cells.push({ x, y, collision: "SOLID" });
        }
      }
    }
    for (const [y, start, end] of platforms) {
      for (let x = start; x <= end; x += 1) {
        cells.push({ x, y, collision: "SOLID" });
      }
    }
    return createGameTilemapDocument({ mapId, width, height, cells });
  };
