      instrument === "MARIMBA" || instrument === "KALIMBA" ||
      instrument === "VIBRAPHONE" || instrument === "XYLOPHONE" ||
      instrument === "CELESTA" || instrument === "TUBULAR_BELLS" ||
      instrument === "STEEL_DRUM"
