      EPIANO: 4,
      ORGAN: 16,
      CLAVINET: 7,
      GUITAR: 24,
      ELECTRIC_GUITAR: 27,
      BASS: 32,
      STRINGS: 48,
      VIOLIN: 40,
      CELLO: 42,
      HARP: 46,
      MARIMBA: 12,
      KALIMBA: 108,
      VIBRAPHONE: 11,
      XYLOPHONE: 13,
      CELESTA: 8,
      TUBULAR_BELLS: 14,
      STEEL_DRUM: 114,
      FLUTE: 73,
      CLARINET: 71,
      SAXOPHONE: 66,
      TRUMPET: 56,
      BRASS: 61,
      SYNTH_LEAD: 80,
      SYNTH_PAD: 88,
      CHIP: 80,
      GB_PULSE_1: 80,
      GB_PULSE_2: 80,
      GB_WAVE: 81,
