        if (existing === undefined) {
          return Promise.resolve({
            ok: true as const,
            value: current,
            diagnostics: [],
          });
        }
        return module.journalWorkspaceAutomationRemove(
          current,
          String(existing.automationId),
          nextAudioWorkspaceMutation("automation-remove"),
        );
