            connections.className = "draw2-game-logic-node-connections";
            connections.textContent = outgoing.length === 0
              ? "接続なし"
              : outgoing.map((edge) => `${edge.port} → ${edge.to}`).join(" · ");
            card.append(heading, detail, connections);
            return card;
