      button.classList.toggle("is-selected", gameVisualMaker.hero.motion === motion.id);
      button.setAttribute("aria-pressed", String(gameVisualMaker.hero.motion === motion.id));
      const symbol = documentRef.createElement("span");
      symbol.textContent = motion.symbol;
      const label = documentRef.createElement("strong");
